-- Guarded reversible correction of Theme 3 and Theme 5. No other palettes changed.
-- Original 8-palette backup: governance/backups/loc-theme-20261008-before-four-four.json
-- Theme 3: coherent orange / apricot / cream; Theme 5: light goose yellow.
-- Both schemes remain Light; names, identity color, style key and group preserved.
do $theme35$
declare
  changes integer;
  n_tokens integer;
  dark_count integer;
  light_count integer;
begin
  update silver.loc_theme
  set theme_attr=jsonb_set(theme_attr,'{tokens}','{"--loc-bg":"#ff8a00","--loc-panel":"#fff6e9","--loc-panel-2":"#ffe1b5","--loc-panel-strong":"rgba(255,246,233,.96)","--loc-panel-nav":"rgba(255,244,226,.97)","--loc-panel-tab":"rgba(255,225,181,.95)","--loc-rune-bg":"#fff8ef","--loc-rune-selected-bg":"#ffc879","--loc-line":"rgba(199,100,0,.28)","--loc-line-soft":"rgba(199,100,0,.13)","--loc-line-softer":"rgba(199,100,0,.17)","--loc-line-faint":"rgba(199,100,0,.19)","--loc-text":"#3b3024","--loc-muted":"#715944","--loc-heading":"#30261e","--loc-accent":"#b75000","--loc-gold":"#a54d00","--loc-danger":"#aa354a","--loc-surface":"rgba(255,246,233,.95)","--loc-surface-soft":"rgba(255,160,48,.095)","--loc-surface-faint":"rgba(255,160,48,.045)","--loc-surface-status":"rgba(255,160,48,.085)","--loc-accent-surface":"rgba(255,138,0,.12)","--loc-accent-surface-strong":"rgba(255,138,0,.20)","--loc-accent-border":"rgba(183,80,0,.55)","--loc-accent-border-soft":"rgba(183,80,0,.42)","--loc-accent-border-faint":"rgba(183,80,0,.30)","--loc-gold-surface":"rgba(165,77,0,.10)","--loc-gold-surface-soft":"rgba(165,77,0,.06)","--loc-gold-border":"rgba(165,77,0,.54)","--loc-gold-border-soft":"rgba(165,77,0,.40)","--loc-gold-border-faint":"rgba(165,77,0,.30)","--loc-gold-ring":"rgba(165,77,0,.26)","--loc-gold-ring-soft":"rgba(165,77,0,.16)","--loc-danger-border":"rgba(170,53,74,.32)","--loc-primary-start":"#ffca80","--loc-primary-end":"#ffa63b","--loc-body-glow":"#ffc270","--loc-body-mid":"#fff0d6","--loc-hero-start":"rgba(255,209,149,.96)","--loc-hero-end":"rgba(255,247,234,.98)","--loc-shadow":"0 20px 55px rgba(85,53,21,.13)","--loc-shadow-card":"0 12px 35px rgba(85,53,21,.09)"}'::jsonb,true)
  where theme_id='theme-3'
    and theme_name='生命'
    and theme_order=3
    and theme_attr='{"group":"生命","scheme":"light","tokens":{"--loc-bg":"#ff8a00","--loc-gold":"#a14300","--loc-line":"rgba(122,63,14,.30)","--loc-text":"#4a2508","--loc-muted":"#8a5a2b","--loc-panel":"#fff1dc","--loc-accent":"#9b4300","--loc-danger":"#9a4040","--loc-shadow":"0 20px 55px rgba(122,63,14,.16)","--loc-heading":"#6b2e00","--loc-panel-2":"#ffd39a","--loc-rune-bg":"#fff6e8","--loc-surface":"rgba(255,241,220,.92)","--loc-body-mid":"#fff0dc","--loc-hero-end":"rgba(255,249,241,.98)","--loc-body-glow":"#ffd5a6","--loc-gold-ring":"rgba(161,67,0,.25)","--loc-line-soft":"rgba(122,63,14,.15)","--loc-panel-nav":"rgba(255,232,194,.97)","--loc-panel-tab":"rgba(255,211,154,.95)","--loc-hero-start":"rgba(255,216,168,.97)","--loc-line-faint":"rgba(122,63,14,.19)","--loc-gold-border":"rgba(161,67,0,.58)","--loc-line-softer":"rgba(122,63,14,.17)","--loc-primary-end":"#e39332","--loc-shadow-card":"0 12px 35px rgba(122,63,14,.10)","--loc-gold-surface":"rgba(161,67,0,.10)","--loc-panel-strong":"rgba(255,241,220,.96)","--loc-surface-soft":"rgba(155,67,0,.055)","--loc-accent-border":"rgba(155,67,0,.58)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#f1b15f","--loc-surface-faint":"rgba(155,67,0,.03)","--loc-accent-surface":"rgba(155,67,0,.10)","--loc-gold-ring-soft":"rgba(161,67,0,.15)","--loc-surface-status":"rgba(155,67,0,.07)","--loc-gold-border-soft":"rgba(161,67,0,.44)","--loc-rune-selected-bg":"#ffc36c","--loc-gold-border-faint":"rgba(161,67,0,.34)","--loc-gold-surface-soft":"rgba(161,67,0,.07)","--loc-accent-border-soft":"rgba(155,67,0,.44)","--loc-accent-border-faint":"rgba(155,67,0,.34)","--loc-accent-surface-strong":"rgba(155,67,0,.18)"},"style_key":"life","identity_color":"#ff8a00"}'::jsonb;
  get diagnostics changes=row_count;
  if changes<>1 then raise exception 'Theme theme-3 differs from original backup: no overwrite permitted'; end if;
  select count(*) into n_tokens from jsonb_object_keys((select theme_attr->'tokens' from silver.loc_theme where theme_id='theme-3'));
  if n_tokens<>43 then raise exception 'theme-3 lost token contract'; end if;
  update silver.loc_theme
  set theme_attr=jsonb_set(theme_attr,'{tokens}','{"--loc-bg":"#fff5bf","--loc-panel":"#fffbe4","--loc-panel-2":"#f8e99f","--loc-panel-strong":"rgba(255,251,228,.98)","--loc-panel-nav":"rgba(255,250,213,.97)","--loc-panel-tab":"rgba(250,239,174,.95)","--loc-rune-bg":"#fffeed","--loc-rune-selected-bg":"#f4e185","--loc-line":"rgba(129,111,44,.26)","--loc-line-soft":"rgba(129,111,44,.12)","--loc-line-softer":"rgba(129,111,44,.16)","--loc-line-faint":"rgba(129,111,44,.18)","--loc-text":"#343224","--loc-muted":"#666347","--loc-heading":"#29291c","--loc-accent":"#746007","--loc-gold":"#806407","--loc-danger":"#a63f4e","--loc-surface":"rgba(255,251,228,.96)","--loc-surface-soft":"rgba(171,145,39,.065)","--loc-surface-faint":"rgba(171,145,39,.035)","--loc-surface-status":"rgba(171,145,39,.08)","--loc-accent-surface":"rgba(138,117,24,.10)","--loc-accent-surface-strong":"rgba(138,117,24,.18)","--loc-accent-border":"rgba(117,94,10,.55)","--loc-accent-border-soft":"rgba(117,94,10,.43)","--loc-accent-border-faint":"rgba(117,94,10,.32)","--loc-gold-surface":"rgba(128,100,7,.10)","--loc-gold-surface-soft":"rgba(128,100,7,.06)","--loc-gold-border":"rgba(128,100,7,.56)","--loc-gold-border-soft":"rgba(128,100,7,.43)","--loc-gold-border-faint":"rgba(128,100,7,.32)","--loc-gold-ring":"rgba(128,100,7,.26)","--loc-gold-ring-soft":"rgba(128,100,7,.15)","--loc-danger-border":"rgba(166,63,78,.30)","--loc-primary-start":"#f9e78f","--loc-primary-end":"#eed771","--loc-body-glow":"#fff0a1","--loc-body-mid":"#fffbd4","--loc-hero-start":"rgba(255,242,174,.96)","--loc-hero-end":"rgba(255,252,229,.98)","--loc-shadow":"0 20px 55px rgba(93,78,25,.12)","--loc-shadow-card":"0 12px 35px rgba(93,78,25,.08)"}'::jsonb,true)
  where theme_id='theme-5'
    and theme_name='礦物'
    and theme_order=5
    and theme_attr='{"group":"礦物","scheme":"light","tokens":{"--loc-bg":"#d9c878","--loc-gold":"#6b5715","--loc-line":"rgba(92,79,34,.30)","--loc-text":"#3e3823","--loc-muted":"#716844","--loc-panel":"#f7efc4","--loc-accent":"#75611a","--loc-danger":"#9a4040","--loc-shadow":"0 20px 55px rgba(92,79,34,.16)","--loc-heading":"#2d2818","--loc-panel-2":"#c6b45f","--loc-rune-bg":"#efe4ad","--loc-surface":"rgba(247,239,196,.92)","--loc-body-mid":"#e9dfaa","--loc-hero-end":"rgba(247,239,196,.99)","--loc-body-glow":"#d2bf69","--loc-gold-ring":"rgba(107,87,21,.28)","--loc-line-soft":"rgba(92,79,34,.15)","--loc-panel-nav":"rgba(226,211,143,.97)","--loc-panel-tab":"rgba(235,222,158,.95)","--loc-hero-start":"rgba(226,211,137,.98)","--loc-line-faint":"rgba(92,79,34,.19)","--loc-gold-border":"rgba(107,87,21,.62)","--loc-line-softer":"rgba(92,79,34,.17)","--loc-primary-end":"#bba64b","--loc-shadow-card":"0 12px 35px rgba(92,79,34,.10)","--loc-gold-surface":"rgba(107,87,21,.12)","--loc-panel-strong":"rgba(247,239,196,.96)","--loc-surface-soft":"rgba(107,87,21,.055)","--loc-accent-border":"rgba(107,87,21,.60)","--loc-danger-border":"rgba(154,64,64,.30)","--loc-primary-start":"#d8c56d","--loc-surface-faint":"rgba(107,87,21,.03)","--loc-accent-surface":"rgba(117,97,26,.12)","--loc-gold-ring-soft":"rgba(107,87,21,.17)","--loc-surface-status":"rgba(107,87,21,.07)","--loc-gold-border-soft":"rgba(107,87,21,.48)","--loc-rune-selected-bg":"#c9b45a","--loc-gold-border-faint":"rgba(107,87,21,.38)","--loc-gold-surface-soft":"rgba(107,87,21,.08)","--loc-accent-border-soft":"rgba(107,87,21,.46)","--loc-accent-border-faint":"rgba(107,87,21,.36)","--loc-accent-surface-strong":"rgba(117,97,26,.20)"},"style_key":"mineral","identity_color":"#c7cdd3"}'::jsonb;
  get diagnostics changes=row_count;
  if changes<>1 then raise exception 'Theme theme-5 differs from original backup: no overwrite permitted'; end if;
  select count(*) into n_tokens from jsonb_object_keys((select theme_attr->'tokens' from silver.loc_theme where theme_id='theme-5'));
  if n_tokens<>43 then raise exception 'theme-5 lost token contract'; end if;
  select count(*) filter (where theme_attr->>'scheme'='dark'),
         count(*) filter (where theme_attr->>'scheme'='light')
    into dark_count,light_count from silver.loc_theme;
  if dark_count<>4 or light_count<>4 then raise exception 'Expected 4 Dark / 4 Light, got % / %',dark_count,light_count; end if;
end $theme35$;
